// B-1 안전장치: 한 실행에 여러 아이템이 들어와도 첫 번째 하나만 처리한다.
// → 하류의 모든 .first() 참조가 절대 다른 손님 값을 집을 수 없게 원천 봉쇄.
const items = $input.all();
if (items.length > 1) {
  console.log('[Extract Event] 다중 아이템 감지:', items.length, '개 → 첫 번째만 처리');
}
const first = items[0].json;
const body = first.body;
// LINE 재전송(redelivery)은 무시 — 만료된 replyToken으로 인한 무한 루프 방지
if (body.events?.[0]?.deliveryContext?.isRedelivery === true) {
  return [{ json: { skip: true } }];
}
const salon_id = first.salon_id ?? null;
const line_token = first.line_token ?? null;
const line_staff_id = first.line_staff_id ?? null;
const unregistered = first.unregistered === true;
const event = body.events?.[0];
if (!event) {
  return [{ json: { skip: true, salon_id, line_token, line_staff_id } }];
}
// ===== 간이 언어 감지 (AI 이전 단계 전용 — 시스템 메시지 언어 선택용) =====
// 문자 체계만으로 판정. 판정 불가(스티커·이미지·기호만)면 '' → 시스템 메시지는 3개 국어 폴백.
const t = event.message?.text ?? '';
let preLang = '';
if (/[\u0E00-\u0E7F]/.test(t)) preLang = 'th';
else if (/[\uAC00-\uD7A3]/.test(t)) preLang = 'ko';
else if (/[\u4E00-\u9FFF]/.test(t)) preLang = 'zh';
else if (/[A-Za-z]/.test(t)) preLang = 'en';
// ===== 직원 명령 감지 (선제형 AI on/off + 메뉴 내비게이션) =====
// 발신자(userId)가 이 살롱의 직원(line_staff_id)과 같은가?
const senderId = event.source?.userId ?? null;
const isStaff = !!senderId && senderId === line_staff_id;
// 직원이 보낸 메시지가 명령어 패턴인지 판정 (대소문자 무시, 앞뒤 공백 제거)
const cmdText = (event.message?.text ?? '').trim().toLowerCase();
let staffCommand = null;   // 'menu' | 'number' | 'list' | 'more' | 'off' | 'on' | null
let staffCommandNum = null; // "AI OFF 3"의 3, 또는 메뉴 번호
if (isStaff) {
  if (cmdText === 'menu') {
    // 메뉴 열기 → 언제나 메인으로 (홈 버튼)
    staffCommand = 'menu';
  } else if (cmdText === 'confirm') {
    staffCommand = 'confirm'
  } else if (/^\d+$/.test(cmdText)) {
    // 순수 번호만 온 경우 → 메뉴 선택 (해석은 menu_state 조회 후 Route Menu가 판단)
    staffCommand = 'number';
    staffCommandNum = parseInt(cmdText, 10);
  } else if (cmdText === 'ai list') {
    staffCommand = 'list';
  } else if (cmdText === 'more') {
    staffCommand = 'more';
  } else {
    const offMatch = cmdText.match(/^ai off (\d+)$/);
    const onMatch = cmdText.match(/^ai on (\d+)$/);
    if (offMatch) {
      staffCommand = 'off';
      staffCommandNum = parseInt(offMatch[1], 10);
    } else if (onMatch) {
      staffCommand = 'on';
      staffCommandNum = parseInt(onMatch[1], 10);
    }
  }
}
const result = {
  type: event.type,
  replyToken: event.replyToken,
  userId: event.source?.userId,
  groupId: event.source?.groupId ?? null,
  messageType: event.message?.type ?? null,
  messageText: event.message?.text ?? null,
  preLang,
  timestamp: event.timestamp,
  salon_id,
  line_token,
  line_staff_id,
  isStaff,           // 발신자가 이 살롱 직원인가
  staffCommand,      // 'menu' | 'number' | 'list' | 'more' | 'off' | 'on' | null
  staffCommandNum,   // "AI OFF 3" → 3, 메뉴 번호, 없으면 null
  unregistered
};
return [{ json: result }];

