const output = $('AI Agent').first().json.output;

// [BOOKING_CONFIRMED] 뒤의 JSON만 추출
const match = output.match(/\[BOOKING_CONFIRMED\]\s*(\{[^}]*\})/);
const booking = match ? JSON.parse(match[1]) : {};

// 손님에게 보낼 메시지 (태그·JSON 제거)
const customerMessage = output
  .replace(/\[BOOKING_CONFIRMED\]\s*\{[^}]*\}/, '')
  .replace(/^[\s\-]+/, '')
  .trim();

// 손님 언어 감지
const userMsg = $('Extract Event').first().json.messageText ?? '';
const combined = userMsg + ' ' + customerMessage;
let lang = 'en';
if (/[\u0E00-\u0E7F]/.test(combined)) lang = 'th';
else if (/[\uAC00-\uD7A3]/.test(combined)) lang = 'ko';
else if (/[\u4E00-\u9FFF]/.test(combined)) lang = 'zh';

// 슬롯 충돌 메시지 (언어별)
const slotTakenMsg = {
  th: "ขออภัยค่ะ เวลานี้มีคิวแล้ว 🙏 รบกวนเลือกเวลาอื่นนะคะ",
  ko: "죄송해요, 그 시간은 이미 예약이 있어요 🙏 다른 시간을 골라주세요",
  zh: "抱歉，这个时间已经被预约了 🙏 请选择其他时间",
  en: "Sorry, that time is already booked 🙏 Please choose another time"
}[lang];

// 예약 후 안내(위치/주차 등) — Config의 afterbook_언어 칸 직접 읽기
const cfg = $('Get Salon Config').first().json;
let locationMsg = cfg['afterbook_' + lang] || '';   // 손님 언어 칸
if (!locationMsg) locationMsg = cfg.afterbook_en || '';  // 없으면 영어 폴백

// 예약 저장 실패 시 손님 안내 (언어별)
const pendingMsg = {
  th: "กรุณารอสักครู่นะคะ 🙏 ระบบกำลังตรวจสอบการจองค่ะ เดี๋ยวเจ้าหน้าที่จะติดต่อกลับเพื่อยืนยันค่ะ 😊",
  ko: "잠시만 기다려 주세요 🙏 예약을 확인하고 있어요. 곧 직원이 확인 후 연락드릴게요 😊",
  zh: "请稍等一下 🙏 我们正在确认您的预约，工作人员稍后会与您联系确认 😊",
  en: "Please wait a moment 🙏 We're confirming your booking. A staff member will contact you shortly to confirm 😊"
}[lang];

return {
  json: {
    ...booking,
    customerMessage,
    slotTakenMsg,
    locationMsg,
    pendingMsg,
    lang
  }
};

const reqDate = $('Parse Booking').first().json.date;   // "2026-06-29"
const reqTime = $('Parse Booking').first().json.time;   // "12:00"
const customerMessage = $('Parse Booking').first().json.customerMessage ?? '';

// 손님 언어 감지
let lang = 'en';
if (/[\u0E00-\u0E7F]/.test(customerMessage)) lang = 'th';
else if (/[\uAC00-\uD7A3]/.test(customerMessage)) lang = 'ko';
else if (/[\u4E00-\u9FFF]/.test(customerMessage)) lang = 'zh';

// 1) 예약 충돌 (Bookings)
const bookings = $('Check Slot').all().filter(i => i.json.id);
const bookingTaken = bookings.length > 0;

// 2) 디자이너 블로킹 (Get Designer Blocks: Neon)
const blocks = $('Get Designer Blocks').all();
let isBlocked = false, blockStart = null, blockEnd = null, allDay = false;
for (const b of blocks) {
  if (!b.json.date_start) continue;
  const blockDate = String(b.json.date_start ?? '').slice(0, 10);
  if (blockDate !== reqDate) continue;
  const start = b.json.time_start ?? null;
  const end   = b.json.time_end ?? null;
  if (start === 'all' || end === 'all') { isBlocked = true; allDay = true; break; }
  if (start && end && start <= reqTime && reqTime < end) {
    isBlocked = true; blockStart = start; blockEnd = end; break;
  }
}

// 3) 미용실 특정 공휴일 (Get Salon Closures: Neon) — 종일(all)
const salonBlocks = $('Get Salon Closures').all();
let isSalonHoliday = false;
for (const b of salonBlocks) {
  const r = b.json;
  const blockDate = String(r?.date_start ?? '').slice(0, 10);
  if (blockDate !== reqDate) continue;
  const tStart = r?.time_start ?? '';
  const tEnd   = r?.time_end ?? '';
  if (tStart === 'all' || tEnd === 'all') { isSalonHoliday = true; break; }
}

// 4) ★ 정기휴무 요일 (매주 X요일) — AI가 요일 오판해도 코드가 최종 차단 ★
//    Build Schedule이 이미 계산한 휴무요일(closedDaysText)을 그대로 재사용
const weekdayNames = ['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
const reqWeekday = weekdayNames[new Date(reqDate + 'T00:00:00Z').getUTCDay()];
const closedDaysText = ($('Build Schedule').first().json.closedDaysText || '').toLowerCase();
const regClosedDays = closedDaysText.split(',').map(s => s.trim()).filter(s => s);
const isRegularClosed = regClosedDays.includes(reqWeekday);

const unavailable = bookingTaken || isBlocked || isSalonHoliday || isRegularClosed;

// 상황별 메시지 (정기휴무 = 공휴일 > 디자이너 > 예약충돌 순 우선)
let unavailableMsg = '';
if (isRegularClosed || isSalonHoliday) {
  unavailableMsg = {
    th: `ขออภัยค่ะ วันที่ ${reqDate} ทางร้านปิดทำการค่ะ 🙏 รบกวนเลือกวันอื่นนะคะ`,
    ko: `죄송해요, ${reqDate}는 미용실 휴무일이에요 🙏 다른 날을 골라주세요`,
    zh: `抱歉，${reqDate} 本店休息 🙏 请选择其他日期`,
    en: `Sorry, the salon is closed on ${reqDate} 🙏 Please choose another day`
  }[lang];
} else if (isBlocked && allDay) {
  unavailableMsg = {
    th: `วันนี้ดีไซเนอร์หยุดค่ะ 🙏 รบกวนเลือกวันอื่นนะคะ`,
    ko: `그날은 디자이너가 쉬는 날이에요 🙏 다른 날을 골라주세요`,
    en: `The designer is off that day 🙏 Please choose another day`
  }[lang];
} else if (isBlocked) {
  unavailableMsg = {
    th: `ช่วง ${blockStart}-${blockEnd} ดีไซเนอร์ติดธุระส่วนตัวค่ะ 🙏 รบกวนเลือกเวลาอื่นนะคะ`,
    ko: `${blockStart}~${blockEnd}는 디자이너가 개인 사정으로 잠시 자리를 비워요 🙏 다른 시간을 골라주세요`,
    en: `The designer is away for personal reasons from ${blockStart} to ${blockEnd} 🙏 Please choose another time`
  }[lang];
} else if (bookingTaken) {
  unavailableMsg = {
    th: `ขออภัยค่ะ เวลานี้มีคิวแล้ว 🙏 รบกวนเลือกเวลาอื่นนะคะ`,
    ko: `죄송해요, 그 시간은 이미 예약이 있어요 🙏 다른 시간을 골라주세요`,
    en: `Sorry, that time is already booked 🙏 Please choose another time`
  }[lang];
}

return [{
  json: {
    ...$('Parse Booking').first().json,
    unavailable, bookingTaken, isBlocked, isSalonHoliday, isRegularClosed, unavailableMsg
  }
}];

const output = $('AI Agent').first().json.output;
const userId = $('Extract Event').first().json.userId;
const customerMessage = $('Extract Event').first().json.messageText ?? '';

// [BOOKING_CANCEL: 2026-06-22 16:00]
const m = output.match(/\[BOOKING_CANCEL:\s*(\d{4}-\d{2}-\d{2})\s+(\d{2}:\d{2})\]/);
const date = m ? m[1] : null;
const time = m ? m[2] : null;

// 손님 언어 감지
let lang = 'en';
if (/[\u0E00-\u0E7F]/.test(customerMessage)) lang = 'th';
else if (/[\uAC00-\uD7A3]/.test(customerMessage)) lang = 'ko';
else if (/[\u4E00-\u9FFF]/.test(customerMessage)) lang = 'zh';

// 취소 완료 메시지
const cancelMsg = {
  th: `ยกเลิกการจองวันที่ ${date} เวลา ${time} เรียบร้อยแล้วค่ะ 🙏 ขอบคุณค่ะ`,
  ko: `${date} ${time} 예약이 취소되었어요 🙏 이용해 주셔서 감사합니다`,
  zh: `${date} ${time} 的预约已取消 🙏 谢谢您`,
  en: `Your booking on ${date} at ${time} has been cancelled 🙏 Thank you`
}[lang];

// 예약 못 찾음 → 직원 연결 안내
const notFoundMsg = {
  th: `ขออภัยค่ะ ไม่พบการจองในเวลาดังกล่าว 🙏 เดี๋ยวเจ้าหน้าที่จะติดต่อกลับนะคะ`,
  ko: `죄송해요, 해당 시간에 예약을 찾지 못했어요 🙏 잠시 후 직원이 연락드릴게요`,
  zh: `抱歉，未能找到该时间的预约 🙏 工作人员稍后会与您联系`,
  en: `Sorry, we couldn't find a booking at that time 🙏 A staff member will contact you shortly`
}[lang];

// 취소 검증 실패 → 직원 확인 안내
const verifyFailMsg = {
  th: `กำลังดำเนินการยกเลิกให้นะคะ 🙏 เดี๋ยวเจ้าหน้าที่จะยืนยันอีกครั้งค่ะ 😊`,
  ko: `취소를 처리하고 있어요 🙏 곧 직원이 확인 후 다시 연락드릴게요 😊`,
  zh: `正在为您处理取消 🙏 工作人员稍后会再次与您确认 😊`,
  en: `We're processing your cancellation 🙏 A staff member will confirm with you shortly 😊`
}[lang];

return [{ json: { userId, date, time, lang, cancelMsg, notFoundMsg, verifyFailMsg } }];

