const output = $('AI Agent').first().json.output;
const userId = $('Extract Event').first().json.userId;
const customerMessage = $('Extract Event').first().json.messageText ?? '';

// [BOOKING_CHANGE]{...}
const match = output.match(/\[BOOKING_CHANGE\]\s*(\{[^}]*\})/);
const change = match ? JSON.parse(match[1]) : {};

// 손님 언어 감지
let lang = 'en';
if (/[\u0E00-\u0E7F]/.test(customerMessage)) lang = 'th';
else if (/[\uAC00-\uD7A3]/.test(customerMessage)) lang = 'ko';
else if (/[\u4E00-\u9FFF]/.test(customerMessage)) lang = 'zh';

// 못 찾음 → 직원 연결
const notFoundMsg = {
  th: `ขออภัยค่ะ ไม่พบการจองเดิม 🙏 เดี๋ยวเจ้าหน้าที่จะติดต่อกลับนะคะ`,
  ko: `죄송해요, 변경하실 기존 예약을 찾지 못했어요 🙏 잠시 후 직원이 연락드릴게요`,
  zh: `抱歉，未能找到原预约 🙏 工作人员稍后会与您联系`,
  en: `Sorry, we couldn't find your existing booking 🙏 A staff member will contact you shortly`
}[lang];

// 변경 완료
const changedMsg = {
  th: `เปลี่ยนการจองเป็นวันที่ ${change.new_date} เวลา ${change.new_time} เรียบร้อยแล้วค่ะ 🙏`,
  ko: `예약이 ${change.new_date} ${change.new_time}로 변경되었어요 🙏`,
  zh: `预约已更改为 ${change.new_date} ${change.new_time} 🙏`,
  en: `Your booking has been changed to ${change.new_date} at ${change.new_time} 🙏`
}[lang];

// 변경 검증 실패 → 직원 확인 안내
const verifyFailMsg = {
  th: `กำลังดำเนินการเปลี่ยนแปลงให้นะคะ 🙏 เดี๋ยวเจ้าหน้าที่จะยืนยันอีกครั้งค่ะ 😊`,
  ko: `예약 변경을 처리하고 있어요 🙏 곧 직원이 확인 후 다시 연락드릴게요 😊`,
  zh: `正在为您处理预约变更 🙏 工作人员稍后会再次与您确认 😊`,
  en: `We're processing your change 🙏 A staff member will confirm with you shortly 😊`
}[lang];

// 변경 충돌 → 새 슬롯을 누가 먼저 차지 → 기존 예약 유지
const conflictMsg = {
  th: `ขออภัยค่ะ เวลาใหม่ที่เลือกเพิ่งมีคนจองไปค่ะ 🙏 การจองเดิมของคุณยังอยู่เหมือนเดิมนะคะ 😊`,
  ko: `죄송해요, 변경하려는 시간이 방금 다른 분께 예약됐어요 🙏 기존 예약은 그대로 유지돼요 😊`,
  zh: `抱歉，您想改的时间刚被别人预约了 🙏 您原来的预约仍然保留 😊`,
  en: `Sorry, the new time was just booked by someone else 🙏 Your original booking is unchanged 😊`
}[lang];

return [{
  json: {
    userId, lang,
    old_date: change.old_date ?? null,
    old_time: change.old_time ?? null,
    new_date: change.new_date ?? null,
    new_time: change.new_time ?? null,
    new_designer: change.new_designer ?? null,
    new_menu: change.new_menu ?? null,
    notFoundMsg, changedMsg, verifyFailMsg, conflictMsg
  }
}];

