// Get My Bookings(Neon)가 가져온 활성 예약들 — 쿼리가 이미 필터·정렬·시간변환 완료
const rows = $('Get My Bookings').all();

// 쿼리에서 이미 방콕 date/time, active, 미래, 정렬이 끝났으므로 그대로 사용
// (Always Output Data로 0건일 때 빈 {}가 올 수 있으니 id 있는 행만)
const bookings = rows
  .filter(r => r.json && r.json.id)
  .map(r => ({
    bookingId: r.json.id,
    date: r.json.date,      // 2026-07-05 (방콕)
    time: r.json.time,      // 14:00 (방콕)
    menu: r.json.menu,
    designer: r.json.designer
  }));

// AI 프롬프트용 텍스트
let bookingContext;
if (bookings.length === 0) {
  bookingContext = 'This customer has NO active upcoming bookings.';
} else if (bookings.length === 1) {
  const b = bookings[0];
  bookingContext = `This customer has ONE active booking:\n- ${b.date} ${b.time} (${b.menu}, ${b.designer})\nIf they ask to change or cancel without specifying which booking, use THIS one automatically. Do not ask which booking.`;
} else {
  const list = bookings.map((b, i) => `${i + 1}. ${b.date} ${b.time} (${b.menu}, ${b.designer})`).join('\n');
  bookingContext = `This customer has MULTIPLE active bookings:\n${list}\nIf they ask to change or cancel without specifying which one, show this numbered list and ask which booking they mean. Do NOT guess.`;
}

return [{
  json: {
    ...$('Extract Event').first().json,
    bookingContext,
    bookingCount: bookings.length
  }
}];

