// ===== 정기 휴무 설정 읽기 (Neon: regular_closures) =====
const reg = $('Get Regular Closure').first()?.json ?? {};

const closedType = (reg.closed_type || '').trim().toLowerCase();   // none / weekly / biweekly
const closedDayRaw = (reg.closed_day || '').trim();               // "Thursday" 또는 "Tuesday, Wednesday"

// 정기 휴무 요일들을 배열로 (여러 개 쉼표 대응) + 소문자
const closedDays = closedDayRaw
  .split(',')
  .map(d => d.trim().toLowerCase())
  .filter(d => d.length > 0);

// ===== 특별 휴무(공휴일 등) 날짜 — Neon: special_closures salon타입 종일 휴무 =====
const salonBlocks = $('Get Salon Closures').all();
const holidayDates = salonBlocks
  .map(b => {
    const r = b.json;
    const dateStart = r?.date_start ?? '';
    const tStart = r?.time_start ?? '';
    const tEnd   = r?.time_end ?? '';
    return { date: String(dateStart).slice(0, 10), tStart, tEnd };
  })
  .filter(b => b.date && (b.tStart === 'all' || b.tEnd === 'all'))
  .map(b => b.date);

// ===== 디자이너 개인 휴무표 (Neon: Get All Designer Closures) =====
const designerClosures = $('Get All Designer Closures').all();
const designerLines = designerClosures
  .map(b => b.json)
  .filter(r => r && r.designer_id && r.date_start)
  .map(r => {
    const date = String(r.date_start).slice(0, 10);
    const ts = r.time_start || '';
    const te = r.time_end || '';
    const span = (ts === 'all' || te === 'all') ? 'ALL DAY' : `${ts}-${te}`;
    return `- ${r.designer_id}: ${date} ${span}  →  OFF / NOT AVAILABLE (never book or reschedule into this slot)`;
  });
const designerAvailText = designerLines.length > 0
  ? designerLines.join('\n')
  : '(No designer time-off in this period.)';

// ===== 날짜 유틸 =====
const weekdayNames = ['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];

function bangkokDate(offsetDays) {
  const now = new Date();
  const bkk = new Date(now.getTime() + (7 * 60 - now.getTimezoneOffset()) * 60000);
  bkk.setDate(bkk.getDate() + offsetDays);
  return bkk;
}

function fmtDate(d) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

// ===== 이 날짜가 휴무인가? =====
function isClosed(dateObj) {
  const weekdayName = weekdayNames[dateObj.getDay()];
  const dateStr = fmtDate(dateObj);
  if (closedType === 'weekly' && closedDays.includes(weekdayName)) return true;
  if (holidayDates.includes(dateStr)) return true;
  return false;
}

// ===== 20일치 전체 날짜표 (AI 참조용 — 요일 환각 방지) =====
const dayRows = [];
for (let i = 0; i < 20; i++) {
  const d = bangkokDate(i);
  const wd = weekdayNames[d.getDay()];
  const wdShort = wd.charAt(0).toUpperCase() + wd.slice(1, 3);
  const status = isClosed(d) ? 'CLOSED' : 'open';
  dayRows.push(`${fmtDate(d)} (${wdShort}) ${status}`);
}

const rangeStart = fmtDate(bangkokDate(0));
const rangeEnd = fmtDate(bangkokDate(19));

const scheduleText = `Schedule for ${rangeStart} ~ ${rangeEnd}. Each line is: DATE (weekday) open/CLOSED.
For ANY date the customer mentions, FIND that exact date in this table and read its weekday and status directly. NEVER compute the weekday yourself — this table is the only truth.
(Internal reference only — do NOT list these rows to the customer. For a general "when are you closed?" question, answer with the weekly rule in ONE short sentence, never this table.)
${dayRows.join('\n')}`;

// ===== 각 요일의 "다음 해당 날짜" (AI가 요일→날짜 계산 못 하게 미리 떠먹여줌) =====
const nextByWeekday = {};
for (let i = 0; i < 45; i++) {
  const d = bangkokDate(i);
  const wd = weekdayNames[d.getDay()];
  if (!nextByWeekday[wd]) {
    nextByWeekday[wd] = `${fmtDate(d)}${isClosed(d) ? ' (CLOSED that day)' : ''}`;
  }
}
// 각 요일 이름을 4개 언어로 병기 → AI가 손님 언어 단어를 그대로 찾게 (번역 단계 제거)
const weekdayI18n = {
  monday:    'Monday / 월요일 / วันจันทร์ / 星期一',
  tuesday:   'Tuesday / 화요일 / วันอังคาร / 星期二',
  wednesday: 'Wednesday / 수요일 / วันพุธ / 星期三',
  thursday:  'Thursday / 목요일 / วันพฤหัสบดี / 星期四',
  friday:    'Friday / 금요일 / วันศุกร์ / 星期五',
  saturday:  'Saturday / 토요일 / วันเสาร์ / 星期六',
  sunday:    'Sunday / 일요일 / วันอาทิตย์ / 星期日',
};
const weekdayOrder = ['monday','tuesday','wednesday','thursday','friday','saturday','sunday'];
const weekdayNextText = weekdayOrder
  .map(wd => `${weekdayI18n[wd]} → ${nextByWeekday[wd] || '(none)'}`)
  .join('\n');

// ===== "이번주/다음주 + 요일" 확정 표 (AI가 주차 계산 못 하게 코드로 확정) =====
// 주는 월요일 시작(방콕 기준). 오늘이 속한 주 = 이번주, 그 다음 주 = 다음주.
const daysSinceMonday = (bangkokDate(0).getDay() + 6) % 7;
const thisWeekByWd = {};
const nextWeekByWd = {};
for (let i = 0; i < 14; i++) {
  const d = bangkokDate(i);
  const wd = weekdayNames[d.getDay()];
  const wk = Math.floor((i + daysSinceMonday) / 7);   // 0=이번주, 1=다음주
  const entry = `${fmtDate(d)}${isClosed(d) ? ' (CLOSED that day)' : ''}`;
  if (wk === 0 && !thisWeekByWd[wd]) thisWeekByWd[wd] = entry;
  if (wk === 1 && !nextWeekByWd[wd]) nextWeekByWd[wd] = entry;
}
const weekdayFollowingText =
  `If the customer says THIS WEEK ("이번주", "this week", "สัปดาห์นี้", "อาทิตย์นี้", "这周", "本周") + a weekday, read the date from THIS list (NEVER compute it):\n` +
  weekdayOrder.map(wd => `${weekdayI18n[wd]} → ${thisWeekByWd[wd] || '(already passed this week)'}`).join('\n') +
  `\nIf the customer says NEXT WEEK ("다음주", "next week", "สัปดาห์หน้า", "อาทิตย์หน้า", "下周", "下星期") + a weekday, read the date from THIS list:\n` +
  weekdayOrder.map(wd => `${weekdayI18n[wd]} → ${nextWeekByWd[wd]}`).join('\n') +
  `\n(Weeks run Monday–Sunday, Bangkok time. A weekday WITHOUT "this/next week" → use the "Next date for each weekday" list above.)`;

// ===== 손님이 특정 날짜를 언급하면, 그 날짜의 요일·영업여부를 코드가 확정 =====
// (AI가 "날짜→요일"을 자기 머리로 계산하다 틀리는 것을 원천 차단)
const userMsg = $('Extract Event').first().json.messageText ?? '';
let askedDateText = '';

// "7월 15일", "7/15", "2026-07-15", "15일" 등에서 월/일 추출
const mdMatch = userMsg.match(/(\d{1,2})\s*[월\/\-.]\s*(\d{1,2})/);      // 7월 15, 7/15, 7-15
const dayOnly = userMsg.match(/(?<!\d)(\d{1,2})\s*일/);                    // "15일"
let mm = null, dd = null;
if (mdMatch) { mm = parseInt(mdMatch[1], 10); dd = parseInt(mdMatch[2], 10); }
else if (dayOnly) { mm = bangkokDate(0).getMonth() + 1; dd = parseInt(dayOnly[1], 10); }

if (mm && dd) {
  // 45일 범위 안에서 해당 월/일을 찾음 (연도 넘어가는 경우도 자동 처리)
  for (let i = 0; i < 45; i++) {
    const d = bangkokDate(i);
    if ((d.getMonth() + 1) === mm && d.getDate() === dd) {
      const wd = weekdayNames[d.getDay()];
      const wdI18n = weekdayI18n[wd];                 // 4개 언어 요일명
      const status = isClosed(d) ? 'CLOSED (휴무)' : 'open (영업)';
      askedDateText =
        `The customer mentioned ${mm}/${dd}. CONFIRMED FACT (do NOT recompute): ` +
        `${fmtDate(d)} is ${wdI18n}, and the salon is ${status} that day. ` +
        `Use THIS weekday and status exactly.`;
      break;
    }
  }
  if (!askedDateText) {
    askedDateText =
      `The customer mentioned ${mm}/${dd}, which is OUTSIDE the confirmed date range. ` +
      `Do NOT state its weekday or open/closed status. Tell them warmly you'll check ` +
      `availability for that date and staff will confirm — do NOT book it. ` +
      `Start your reply with [ESCALATE].`;
  }
}

// ===== 지금 영업 중인지 =====
const nowBkk = bangkokDate(0);
const todayClosed = isClosed(nowBkk);
const hour = nowBkk.getHours();
const inHours = hour >= 10 && hour < 20;
const openNow = !todayClosed && inHours;

// ===== 휴무 규칙 안내 문장 =====
let closedRuleText;
if (closedType === 'none' || closedDays.length === 0) {
  closedRuleText = 'This salon is open every day with no regular weekly closed day.';
} else if (closedType === 'weekly') {
  const cap = closedDays
    .map(d => d.charAt(0).toUpperCase() + d.slice(1))
    .join(' and ');
  closedRuleText = `This salon is closed every ${cap}.`;
} else {
  closedRuleText = 'See the schedule above for which days are closed.';
}

// ===== 출력 =====
return [{
  json: {
    scheduleText,                          // 45일치 영업/휴무 표
    weekdayNextText,                       // 각 요일의 다음 날짜 (4개 언어 요일명 병기)
    weekdayFollowingText,                  // 이번주/다음주 요일 확정 표
    askedDateText,                         // 손님이 물은 특정 날짜의 확정된 요일·영업여부
    designerAvailText,                     // 디자이너 개인 휴무표
    openNow,                               // 지금 영업 중?
    closedRuleText,                        // "매주 X요일 휴무" 규칙 문장
    closedDaysText: closedDays.join(', '), // 휴무 요일 (참고용)
    holidayDates,                          // 공휴일 날짜들 (참고/디버깅용)
    closedType
  }
}];

