function richText(prop) {
  if (!prop) return '';
  if (Array.isArray(prop.rich_text)) return prop.rich_text.map(t => t.plain_text ?? '').join('');
  if (Array.isArray(prop.title)) return prop.title.map(t => t.plain_text ?? '').join('');
  return '';
}
const cols = ['topic','keywords','answer_th','answer_ko','answer_en','answer_zh'];
return $input.all().map(item => {
  const props = item.json.properties || {};
  const out = { salon_id: richText(props.salon_id) };
  for (const c of cols) out[c] = richText(props[c]);
  return { json: out };
}).filter(r => r.json.salon_id);  // salon_id 없는 행은 건너뜀

// AI 본론
const aiOutput = $('AI Agent').first().json.output ?? '';

// 인사 여부
const shouldGreet = $('Get Status').first().json.should_greet === true;

// 손님 언어: preLang 재사용 (빈 값이면 태국어)
const lang = $('Extract Event').first().json.preLang || 'th';

// 인사말 (없으면 태국어)
const cfg = $('Get Salon Config').first().json;
const greeting = cfg['greeting_' + lang] || cfg.greeting_th || '';

// 조립
let finalText = aiOutput;
if (shouldGreet && greeting) {
  if (aiOutput && aiOutput.trim().length > 0) {
    finalText = greeting + '\n\n' + aiOutput;
  } else {
    finalText = greeting;
  }
}

return [{ json: { finalText, lang, greeted: shouldGreet && !!greeting } }];

