parameters.jsCode:
const reqDate = $('Parse Change').first().json.new_date;   // 새 날짜
const reqTime = $('Parse Change').first().json.new_time;   // 새 시간
const customerMessage = $('Extract Event').first().json.messageText ?? '';

// 자기 자신(옛 예약) page id — 충돌 계산에서 제외할 대상
const oldBookingId = $('Find Old Booking').first().json.id;

// 손님 언어 감지
let lang = 'en';
if (/[\u0E00-\u0E7F]/.test(customerMessage)) lang = 'th';
else if (/[\uAC00-\uD7A3]/.test(customerMessage)) lang = 'ko';
else if (/[\u4E00-\u9FFF]/.test(customerMessage)) lang = 'zh';

// 1) 새 슬롯 예약 충돌 (Bookings) — cancelled 제외 + 자기 자신 제외
const bookings = $('Check New Slot').all().filter(i =>
  i.json.id &&
  i.json.property_status !== 'cancelled' &&
  i.json.id !== oldBookingId          // ← 변경의 핵심 한 줄!
);
const bookingTaken = bookings.length > 0;

// 2) 블로킹 (Get New Designer Blocks: Neon) — 같은 날 + 시간 범위
const blocks = $('Get New Designer Blocks').all();
let isBlocked = false, blockStart = null, blockEnd = null, allDay = false;
for (const b of blocks) {
  if (!b.json.date_start) continue;
  const blockDate = String(b.json.date_start ?? '').slice(0, 10);
  if (blockDate !== reqDate) continue;
  const start = b.json.time_start ?? null;
  const end   = b.json.time_end ?? null;
  if (start === 'all' || end === 'all') { isBlocked = true; allDay = true; break; }
  if (start && end && start <= reqTime && reqTime < end) {
    isBlocked = true; blockStart = start; blockEnd = end; break;
  }
}

// 3) 미용실 특정 공휴일 (Get Salon Closures: Neon) — 종일(all)
const salonBlocks = $('Get Salon Closures').all();
let isSalonHoliday = false;
for (const b of salonBlocks) {
  const r = b.json;
  const blockDate = String(r?.date_start ?? '').slice(0, 10);
  if (blockDate !== reqDate) continue;
  const tStart = r?.time_start ?? '';
  const tEnd   = r?.time_end ?? '';
  if (tStart === 'all' || tEnd === 'all') { isSalonHoliday = true; break; }
}

// 4) ★ 정기휴무 요일 (매주 X요일) — AI가 요일 오판해도 코드가 최종 차단 ★
const weekdayNames = ['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
const reqWeekday = weekdayNames[new Date(reqDate + 'T00:00:00Z').getUTCDay()];
const closedDaysText = ($('Build Schedule').first().json.closedDaysText || '').toLowerCase();
const regClosedDays = closedDaysText.split(',').map(s => s.trim()).filter(s => s);
const isRegularClosed = regClosedDays.includes(reqWeekday);

const unavailable = bookingTaken || isBlocked || isSalonHoliday || isRegularClosed;

// 상황별 메시지 (정기휴무 = 공휴일 > 블로킹 > 예약충돌, 모두 "기존 예약 유지" 톤)
let unavailableMsg = '';
if (isRegularClosed || isSalonHoliday) {
  unavailableMsg = {
    th: `ขออภัยค่ะ วันที่ ${reqDate} ทางร้านปิดทำการค่ะ 🙏 ตอนนี้การจองเดิมยังอยู่นะคะ หากต้องการเปลี่ยน รบกวนเลือกวันอื่นค่ะ`,
    ko: `죄송해요, ${reqDate}는 미용실 휴무일이에요 🙏 현재 기존예약은 그대로 유지돼요. 변경을 원하시면 다른 날을 골라주세요`,
    zh: `抱歉，${reqDate} 本店休息 🙏 原预约仍然保留。如需更改，请选择其他日期`,
    en: `Sorry, the salon is closed on ${reqDate} 🙏 Your original booking is still kept. To change it, please choose another day`
  }[lang];
} else if (isBlocked && allDay) {
  unavailableMsg = {
    th: `ขออภัยค่ะ วันนั้นดีไซเนอร์หยุดค่ะ 🙏 ตอนนี้การจองเดิมยังอยู่นะคะ หากต้องการเปลี่ยน รบกวนเลือกวันอื่นค่ะ`,
    ko: `죄송해요, 그날은 디자이너가 쉬는 날이에요 🙏 현재 기존예약은 그대로 유지돼요. 변경을 원하시면 다른 날을 골라주세요`,
    en: `Sorry, the designer is off that day 🙏 Your original booking is still kept. To change it, please choose another day`
  }[lang];
} else if (isBlocked) {
  unavailableMsg = {
    th: `ขออภัยค่ะ ช่วง ${blockStart}-${blockEnd} ดีไซเนอร์ติดธุระค่ะ 🙏 ตอนนี้การจองเดิมยังอยู่นะคะ หากต้องการเปลี่ยน รบกวนเลือกเวลาอื่นค่ะ`,
    ko: `죄송해요, ${blockStart}~${blockEnd}는 디자이너가 자리를 비워요 🙏 현재 기존예약은 그대로 유지돼요. 변경을 원하시면 다른 시간을 골라주세요`,
    en: `Sorry, the designer is away from ${blockStart} to ${blockEnd} 🙏 Your original booking is still kept. To change it, please choose another time`
  }[lang];
} else if (bookingTaken) {
  unavailableMsg = {
    th: `ขออภัยค่ะ เวลาใหม่มีคิวแล้ว 🙏 ตอนนี้การจองเดิมยังอยู่นะคะ หากต้องการเปลี่ยน รบกวนเลือกเวลาอื่นค่ะ`,
    ko: `죄송해요, 변경하려는 시간은 이미 예약이 있어요 🙏 현재 기존예약은 그대로 유지돼요. 변경을 원하시면 다른 시간을 골라주세요`,
    en: `Sorry, the new time is already booked 🙏 Your original booking is still kept. To change it, please choose another time`
  }[lang];
}

return [{
  json: {
    ...$('Parse Change').first().json,
    oldBookingId,
    unavailable, bookingTaken, isBlocked, isSalonHoliday, isRegularClosed, unavailableMsg
  }
}];

