const rows = $('Get Recent Customers').all().map(r => r.json).filter(r => r && r.user_id);
const isMore = $('Extract Event').first().json.staffCommand === 'more';
const offset = isMore ? 10 : 0;
const lang = $('Get Staff Config').first().json.staff_lang || 'ko';

// ===== 언어 사전 (안내 문구만 번역 / 명령어 AI ON·OFF는 영어 고정) =====
const dict = {
  ko: {
    header: '최근 손님이에요:',
    statusAI: 'AI 작동중',
    statusHuman: '직원 응대중',
    guide: '끄려면 "AI OFF 번호", 켜려면 "AI ON 번호"',
    more: '다음 손님: "more"',
    emptyList: '최근 3일 내 대화한 손님이 없어요. 🙏',
    emptyMore: '더 이상 손님이 없어요. 🙏'
  },
  en: {
    header: 'Recent customers:',
    statusAI: 'AI active',
    statusHuman: 'Staff handling',
    guide: 'To turn off: "AI OFF number", to turn on: "AI ON number"',
    more: 'Next: "more"',
    emptyList: 'No customers in the last 3 days. 🙏',
    emptyMore: 'No more customers. 🙏'
  },
  th: {
    header: 'ลูกค้าล่าสุดค่ะ:',
    statusAI: 'AI ทำงานอยู่',
    statusHuman: 'เจ้าหน้าที่กำลังดูแล',
    guide: 'ปิด AI พิมพ์ "AI OFF หมายเลข", เปิด AI พิมพ์ "AI ON หมายเลข"',
    more: 'ลูกค้าถัดไป: "more"',
    emptyList: 'ไม่มีลูกค้าที่คุยใน 3 วันที่ผ่านมาค่ะ 🙏',
    emptyMore: 'ไม่มีลูกค้าเพิ่มแล้วค่ะ 🙏'
  }
};
const t = dict[lang] || dict.ko;

// 스냅샷: userId만 순서대로 (off/on이 번호로 지목할 배열)
const snapshot = rows.map(r => r.user_id);

let listText;
if (rows.length === 0) {
  listText = isMore ? t.emptyMore : t.emptyList;
} else {
  const lines = rows.map((r, i) => {
    const num = offset + i + 1;
    const name = r.display_name || r.user_id;
    const status = r.mode === 'human' ? t.statusHuman : t.statusAI;
    return `${num}) ${name} [${status}]`;
  });
  listText = t.header + '\n' + lines.join('\n')
    + '\n\n' + t.guide
    + (rows.length === 10 ? '\n' + t.more : '');
}

return [{ json: { listText, snapshot: JSON.stringify(snapshot) } }];

