parameters.jsCode:
const ev = $('Extract Event').first().json;
const lang = $('Get Staff Config (Cmd)').first().json.staff_lang || 'ko';
const cmd = ev.staffCommand;        // 'off' | 'on'
const num = ev.staffCommandNum;     // 1, 2, 3...

// 직원 행에서 스냅샷 조회 (Get Snapshot 노드가 앞에서 읽어옴)
const snapRow = $('Get Snapshot').first().json;
let snapshot = [];
try {
  snapshot = JSON.parse(snapRow?.last_list || '[]');
} catch (e) {
  snapshot = [];
}

// ===== 언어 사전 =====
const dict = {
  ko: {
    noList: '먼저 어떤 주문을 하시겠어요? "AI LIST"로 손님 목록을 먼저 확인해주세요. 🙏',
    badNum: (n) => `${n}번 손님은 목록에 없어요. "AI LIST"로 다시 확인해주세요. 🙏`
  },
  en: {
    noList: 'What would you like to do? Please check the customer list first with "AI LIST". 🙏',
    badNum: (n) => `Customer #${n} is not in the list. Please check again with "AI LIST". 🙏`
  },
  th: {
    noList: 'ต้องการทำอะไรคะ? กรุณาดูรายชื่อลูกค้าก่อนด้วย "AI LIST" ค่ะ 🙏',
    badNum: (n) => `ไม่พบลูกค้าหมายเลข ${n} ในรายการค่ะ กรุณาตรวจสอบอีกครั้งด้วย "AI LIST" ค่ะ 🙏`
  }
};
const t = dict[lang] || dict.ko;

// ===== 경계 검증 =====
let valid = false;
let errorMsg = '';
let targetUserId = null;

if (snapshot.length === 0) {
  // 경계 1: 빈 목록 → 주문 안내
  errorMsg = t.noList;
} else if (!num || num < 1 || num > snapshot.length) {
  // 경계 2: 범위 밖 번호
  errorMsg = t.badNum(num);
} else {
  // 유효: 번호로 userId 지목 (1번 = 배열 [0])
  valid = true;
  targetUserId = snapshot[num - 1];
}

return [{ json: { valid, errorMsg, targetUserId, cmd, num, lang } }];

const v = $('Validate Off/On').first().json;
const changed = $('Change Mode').first().json;
const lang = v.lang;
const cmd = v.cmd;                          // 'off' | 'on'
const name = changed?.display_name || v.targetUserId;
const oldMode = changed?.old_mode;          // 바꾸기 전 상태

// 목표 상태
const targetMode = cmd === 'off' ? 'human' : 'ai';
// 이미 그 상태였나? (경계 3)
const alreadyThere = (oldMode === targetMode);

const dict = {
  ko: {
    offDone: (n) => `${n}님의 AI를 껐어요. 이제 직접 응대해주세요. 😊`,
    onDone: (n) => `${n}님의 AI를 다시 켰어요. 😊`,
    offAlready: (n) => `${n}님은 이미 직원 응대중이에요.`,
    onAlready: (n) => `${n}님은 이미 AI가 작동중이에요.`
  },
  en: {
    offDone: (n) => `AI for ${n} is now off. Please respond directly. 😊`,
    onDone: (n) => `AI for ${n} is back on. 😊`,
    offAlready: (n) => `${n} is already being handled by staff.`,
    onAlready: (n) => `AI is already active for ${n}.`
  },
  th: {
    offDone: (n) => `ปิด AI ของ ${n} แล้วค่ะ กรุณาตอบด้วยตนเองค่ะ 😊`,
    onDone: (n) => `เปิด AI ของ ${n} อีกครั้งแล้วค่ะ 😊`,
    offAlready: (n) => `${n} มีเจ้าหน้าที่ดูแลอยู่แล้วค่ะ`,
    onAlready: (n) => `AI ของ ${n} ทำงานอยู่แล้วค่ะ`
  }
};
const t = dict[lang] || dict.ko;

let replyText;
if (alreadyThere) {
  replyText = cmd === 'off' ? t.offAlready(name) : t.onAlready(name);
} else {
  replyText = cmd === 'off' ? t.offDone(name) : t.onDone(name);
}

// 손님 push는 "실제로 off로 바뀐 경우만" (이미 human이었으면 push 불필요)
const shouldPushCustomer = (cmd === 'off' && !alreadyThere);

return [{ json: {
  replyText,
  shouldPushCustomer,
  targetUserId: v.targetUserId
} }];

