parameters.jsCode:
const ev = $('Extract Event').first().json;
const ctx = $('Get Menu Context').first().json || {};
const cmd = ev.staffCommand;         // 'menu' | 'number'
const num = ev.staffCommandNum;      // 번호
const menuState = ctx.menu_state || null;
const fresh = ctx.menu_fresh === true;
const cmdText = (ev.messageText || '').trim().toLowerCase();

// ===== 메뉴 구조 정의 (데이터) — 항목 추가는 여기만 수정 =====
// 각 화면(state)에서 번호가 무슨 action으로 가는지
const MENU_MAP = {
  main: {
    1: 'goto_customer',   // 손님별 AI 관리
    2: 'goto_all'         // 전체 AI 관리
  },
  all_control: {
    1: 'do_all_on',       // 1번: 전체 켜기 (즉시)
    2: 'ask_all_off'      // 2번: 전체 끄기 (confirm 필요)
  }
};

let action = 'show_main';   // 기본값

if (cmd === 'menu') {
  action = 'show_main';                      // "menu"는 언제나 홈
} else if (menuState === 'all_off_confirm') {
  // 확인 대기 상태: "confirm" 타이핑해야 실행
  if (cmdText === 'confirm') action = 'do_all_off';
  else action = 'cancel_confirm';            // 그 외 입력은 취소
} else if (cmd === 'number') {
  if (!menuState || !fresh) {
    action = 'expired';                       // 메뉴 안 열었거나 3분 지남
  } else {
    const map = MENU_MAP[menuState] || {};
    action = map[num] || 'invalid';
  }
}

return [{ json: {
  action,
  num,
  staff_lang: ctx.staff_lang || 'ko',
  ai_enabled: ctx.ai_enabled
} }];

const r = $('Route Menu').first().json;
const action = r.action;
const lang = r.staff_lang;
const aiEnabled = r.ai_enabled;

// ===== 언어 사전 =====
const dict = {
  ko: {
    main: '메뉴예요:\n1. 손님별 AI 관리\n2. 전체 AI 관리\n\n번호를 보내주세요',
    allCtrl: (on) => `전체 AI 관리\n\n현재 상태: ${on ? '켜짐 ✅' : '꺼짐 ⛔'}\n\n1. 전체 켜기\n2. 전체 끄기`,
    askOff: '⚠️ 정말 전체 AI를 끄시겠어요?\n끄면 모든 손님에게 AI가 응답하지 않아요.\n\n끄려면 "confirm"을 입력, 취소하려면 "menu"',
    doneOff: '전체 AI를 껐어요. ⛔ 이제 모든 손님을 직접 응대해주세요.',
    doneOn: '전체 AI를 다시 켰어요. ✅',
    cancel: '취소했어요. 메인 메뉴로 돌아왔어요.',
    expired: '메뉴가 만료됐어요. "menu"를 다시 입력해주세요. 🙏',
    invalid: '없는 번호예요. 다시 확인해주세요. 🙏'
  },
  en: {
    main: 'Menu:\n1. Manage customer AI\n2. Manage all AI\n\nSend a number',
    allCtrl: (on) => `All AI Control\n\nCurrent: ${on ? 'ON ✅' : 'OFF ⛔'}\n\n1. Turn all on\n2. Turn all off`,
    askOff: '⚠️ Turn off AI for ALL customers?\nNo customer will get AI replies.\n\nType "confirm" to proceed, "menu" to cancel',
    doneOff: 'All AI is now OFF. ⛔ Please handle all customers directly.',
    doneOn: 'All AI is back ON. ✅',
    cancel: 'Cancelled. Back to main menu.',
    expired: 'Menu expired. Please type "menu" again. 🙏',
    invalid: 'Invalid number. Please check again. 🙏'
  },
  th: {
    main: 'เมนูค่ะ:\n1. จัดการ AI รายลูกค้า\n2. จัดการ AI ทั้งหมด\n\nกรุณาส่งหมายเลข',
    allCtrl: (on) => `จัดการ AI ทั้งหมด\n\nสถานะปัจจุบัน: ${on ? 'เปิด ✅' : 'ปิด ⛔'}\n\n1. เปิดทั้งหมด\n2. ปิดทั้งหมด`,
    askOff: '⚠️ ปิด AI สำหรับลูกค้าทุกคนใช่ไหมคะ?\nลูกค้าจะไม่ได้รับการตอบจาก AI\n\nพิมพ์ "confirm" เพื่อยืนยัน, "menu" เพื่อยกเลิก',
    doneOff: 'ปิด AI ทั้งหมดแล้วค่ะ ⛔ กรุณาดูแลลูกค้าทุกคนเองค่ะ',
    doneOn: 'เปิด AI ทั้งหมดอีกครั้งแล้วค่ะ ✅',
    cancel: 'ยกเลิกแล้วค่ะ กลับสู่เมนูหลัก',
    expired: 'เมนูหมดอายุแล้วค่ะ กรุณาพิมพ์ "menu" อีกครั้ง 🙏',
    invalid: 'ไม่มีหมายเลขนี้ค่ะ กรุณาตรวจสอบอีกครั้ง 🙏'
  }
};
const t = dict[lang] || dict.ko;

// action → {저장할 menu_state, 보낼 메시지}
let newState = null;   // null이면 상태 변경 안 함
let replyText = '';

switch (action) {
  case 'show_main':      newState = 'main';            replyText = t.main; break;
  case 'goto_all':       newState = 'all_control';     replyText = t.allCtrl(aiEnabled); break;
  case 'ask_all_off':    newState = 'all_off_confirm'; replyText = t.askOff; break;
  case 'do_all_off':     newState = 'main';            replyText = t.doneOff; break;
  case 'do_all_on':      newState = 'main';            replyText = t.doneOn; break;
  case 'cancel_confirm': newState = 'main';            replyText = t.cancel; break;
  case 'expired':        newState = null;              replyText = t.expired; break;
  case 'invalid':        newState = null;              replyText = t.invalid; break;
  default:               newState = 'main';            replyText = t.main;
}

// 전체 on/off 실행 여부 (Update 노드가 볼 플래그)
const setAiEnabled = (action === 'do_all_off') ? false
                   : (action === 'do_all_on') ? true
                   : null;   // null이면 salon_config 안 건드림

return [{ json: {
  action, newState, replyText, setAiEnabled,
  isGotoCustomer: (action === 'goto_customer')
} }];

